llm_only.sql:
SELECT *
FROM compounds
WHERE elements @> ARRAY['Ni', 'Al']::text[];

SELECT compound_id, formula, a, b, c, alpha, beta, gamma
FROM compounds
WHERE formula ~ '(^|[^A-Za-z])Pt($|[^a-z])';

SELECT *
FROM materials
WHERE structure_type IN ('B2', 'L1₂');

SELECT *
FROM compounds
WHERE strukturbericht_symbol IN ('L1₂', 'L1_2', 'L12');

